insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000990012','40000000-0000-4000-8000-000000990001','Troque $1+e^x$ por uma variável e leve os limites para a nova variável.',2) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000990013','40000000-0000-4000-8000-000000990001','Os valores transformados nos extremos são $2$ e $3$.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990001','$19$','A potência de $1+e^x$ indica a substituição $u=1+e^x$. Como $du=e^x\,dx$, o integrando vira $3u^2\,du$. Os limites $x=0$ e $x=\ln2$ tornam-se $u=2$ e $u=3$. Então $3\int_2^3u^2\,du=[u^3]_2^3=27-8=19$. Por ser definida, a integral não recebe constante; B é a opção correta.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990011','40000000-0000-4000-8000-000000990001','A potência de $1+e^x$ indica a substituição $u=1+e^x$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990012','40000000-0000-4000-8000-000000990001','Como $du=e^x\,dx$, o integrando vira $3u^2\,du$.',2) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990013','40000000-0000-4000-8000-000000990001','Os limites $x=0$ e $x=\ln2$ tornam-se $u=2$ e $u=3$.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
