insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990003','$4$','A integral acumula valores de $t^3-2t$ até o ponto $x$. Pelo Teorema Fundamental, $G\prime(x)=x^3-2x$. Não se deriva o integrando em relação a $t$; o pedido é a derivada de $G$. Em $x=2$, temos $2^3-2\cdot2=4$. Assim, a resposta é a alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990031','40000000-0000-4000-8000-000000990003','A integral acumula valores de $t^3-2t$ até o ponto $x$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
