insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000990052','40000000-0000-4000-8000-000000990005','Uma série geométrica infinita só tem soma quando o módulo da razão é menor que $1$.',2) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
