insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990005','$12/5$','O primeiro termo é $a=3$ e a razão é $r=-1/4$. Como $|r|=1/4<1$, a soma geométrica existe. Aplicamos $S=a/(1-r)$. Logo $S=3/(1+1/4)=12/5$. A alternância de sinais confirma que B, e não uma soma com razão positiva, é correta.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990051','40000000-0000-4000-8000-000000990005','O primeiro termo é $a=3$ e a razão é $r=-1/4$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
