insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000990006','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009901','multiple_choice','easy','published','Para $n\ge1$, seja $a_n=(7n^2-3)/(2n^2+5n)$. Qual é $\lim_{n\to\infty}a_n$?') on conflict (id) do update set subject_id=excluded.subject_id,source_id=excluded.source_id,kind=excluded.kind,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
