insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990006','$7/2$','Os termos dominantes são $7n^2$ e $2n^2$. Dividindo por $n^2$, obtemos $(7-3/n^2)/(2+5/n)$. Quando $n$ cresce, $3/n^2$ e $5/n$ tendem a zero. Resta $7/2$. O limite finito corresponde à alternativa C.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
