insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990007','$1/2$','Escrevemos $\int_1^{\infty}x^{-3}dx=\lim_{b\to\infty}\int_1^b x^{-3}dx$. Uma primitiva é $-1/(2x^2)$. A integral truncada vale $-1/(2b^2)+1/2$. Como $1/(2b^2)$ tende a zero, o limite vale $1/2$. Logo a integral converge; a opção C é correta.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990071','40000000-0000-4000-8000-000000990007','Escrevemos $\int_1^{\infty}x^{-3}dx=\lim_{b\to\infty}\int_1^b x^{-3}dx$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
