insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990010','$1,105$','Substituímos $0,1$ em $P_2$. O termo quadrático vale $0,01/2=0,005$. O termo linear vale $0,1$. A soma é $1+0,1+0,005=1,105$. A opção C traz essa aproximação.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
