insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990014','$1/4$','Com $u=\sin x$, $du=\cos x\,dx$. O integrando passa a ser $u^3$. Os limites tornam-se $0$ e $1$. Temos $[u^4/4]_0^1=1/4$. Logo A é correta.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
