insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990016','Converge por comparação no limite com $1/n^2$.','O termo se comporta como $4n/n^3=4/n^2$. Tomamos $b_n=1/n^2$. O limite de $a_n/b_n$ é $4$. Como $\sum b_n$ converge, a série original converge. B fornece essa justificativa.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
