insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000990212','40000000-0000-4000-8000-000000990021','Escolha $u=\ln x$ e integre $x\,dx$.',2) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000990213','40000000-0000-4000-8000-000000990021','Avalie a primitiva nos dois limites, mantendo o valor de $\ln1$.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990021','$e^2/4+1/4$','Definimos $u=\ln x$ e $dv=x\,dx$. Então $du=dx/x$ e $v=x^2/2$. A primitiva é $x^2\ln x/2-\int x/2\,dx=x^2\ln x/2-x^2/4$. Em $e$ ela vale $e^2/4$; em $1$, vale $-1/4$. A diferença é $(e^2+1)/4$, opção A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990211','40000000-0000-4000-8000-000000990021','Definimos $u=\ln x$ e $dv=x\,dx$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
