insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990022','$\ln|x+1|+\frac12\ln(x^2+4)+C$','Escrevemos $A/(x+1)+(Bx+C)/(x^2+4)$. Igualando coeficientes, obtém-se $A=1$, $B=1$ e $C=0$. A integral vira $\int dx/(x+1)+\int x\,dx/(x^2+4)$. A segunda parcela é $(1/2)\ln(x^2+4)$. O resultado é B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
