insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990023','$2/15$','Escrevemos $\sin^3x=\sin x(1-\cos^2x)$. Tomamos $u=\cos x$, então $du=-\sin x\,dx$. A integral vira $\int_0^1(u^2-u^4)du$ após ajustar os limites. Isso vale $1/3-1/5=2/15$. A troca de limites compensa o sinal; B é correta.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
