insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990024','Diverge porque os dois limites laterais divergem.','O integrando não está definido em $x=0$. Devemos estudar $\int_{-1}^0x^{-2}dx$ e $\int_0^1x^{-2}dx$ separadamente. Em ambos os lados, a primitiva $-1/x$ cresce sem limite positivo ao aproximar zero. Logo nenhum dos dois limites necessários é finito. A integral diverge; C é a conclusão correta.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990241','40000000-0000-4000-8000-000000990024','O integrando não está definido em $x=0$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990242','40000000-0000-4000-8000-000000990024','Devemos estudar $\int_{-1}^0x^{-2}dx$ e $\int_0^1x^{-2}dx$ separadamente.',2) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990243','40000000-0000-4000-8000-000000990024','Em ambos os lados, a primitiva $-1/x$ cresce sem limite positivo ao aproximar zero.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990244','40000000-0000-4000-8000-000000990024','Logo nenhum dos dois limites necessários é finito.',4) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
