insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990025','$p>1$','A função é positiva e decrescente para $x$ grande. No teste da integral, fazemos $u=\ln x$, $du=dx/x$. Surge $\int u^{-p}du$. Essa integral converge no infinito exatamente quando $p>1$. Portanto a resposta é C.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990251','40000000-0000-4000-8000-000000990025','A função é positiva e decrescente para $x$ grande.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
