insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990027','Condicionalmente convergente.','A magnitude $1/(\sqrt n+1)$ tende a zero e é decrescente. O teste alternado garante a convergência da série dada. Tomando valores absolutos, os termos são comparáveis a $1/\sqrt n$. A p-série com $p=1/2$ diverge. Assim há convergência condicional, B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
