insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990030','$4/3$','As interseções satisfazem $x^2=2x$, logo são $x=0$ e $x=2$. Para $x=1$, a reta vale $2$ e a parábola vale $1$. Assim a área é $\int_0^2(2x-x^2)dx$. A avaliação dá $[x^2-x^3/3]_0^2=4-8/3=4/3$. A alternativa C é correta.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990301','40000000-0000-4000-8000-000000990030','As interseções satisfazem $x^2=2x$, logo são $x=0$ e $x=2$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
