insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990031','$1$','Definimos a integral como $\lim_{b\to\infty}\int_1^b\ln x/x^2\,dx$. Por partes, use $u=\ln x$ e $dv=x^{-2}dx$. A primitiva é $-(\ln x+1)/x$. Em $b$, esse valor tende a zero; em $1$, vale $-1$. A diferença é $1$, logo C.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990311','40000000-0000-4000-8000-000000990031','Definimos a integral como $\lim_{b\to\infty}\int_1^b\ln x/x^2\,dx$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990312','40000000-0000-4000-8000-000000990031','Por partes, use $u=\ln x$ e $dv=x^{-2}dx$.',2) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990313','40000000-0000-4000-8000-000000990031','A primitiva é $-(\ln x+1)/x$.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990314','40000000-0000-4000-8000-000000990031','Em $b$, esse valor tende a zero; em $1$, vale $-1$.',4) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
