insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990032','$9/2$','Resolvendo $x+2=x^2$, obtemos $x=-1$ e $x=2$. No ponto $x=0$, a reta está acima da parábola. A área é $\int_{-1}^2(x+2-x^2)dx$. A avaliação resulta em $9/2$. Portanto A é correta.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
