insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990033','$\sqrt2-1$','Defina $u=1+x^2$, então $du=2x\,dx$. Assim $x\,dx=du/2$. Os limites passam de $0,1$ para $1,2$. A integral vale $(1/2)\int_1^2u^{-1/2}du=[\sqrt u]_1^2$. O resultado é $\sqrt2-1$, alternativa A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990331','40000000-0000-4000-8000-000000990033','Defina $u=1+x^2$, então $du=2x\,dx$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990332','40000000-0000-4000-8000-000000990033','Assim $x\,dx=du/2$.',2) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990333','40000000-0000-4000-8000-000000990033','Os limites passam de $0,1$ para $1,2$.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990334','40000000-0000-4000-8000-000000990033','A integral vale $(1/2)\int_1^2u^{-1/2}du=[\sqrt u]_1^2$.',4) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990335','40000000-0000-4000-8000-000000990033','O resultado é $\sqrt2-1$, alternativa A.',5) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
